<?php
namespace App\Http\Controllers;
use App\Models\{ActivityLog,Project}; use Illuminate\Http\Request; use Illuminate\Support\Facades\DB;
class ProjectController extends Controller {
private function scoped(Request $r,int $id):Project{return $r->user()->projects()->whereKey($id)->firstOrFail();}
private function log(Project $p,Request $r,string $event,array $details=[]):void{ActivityLog::create(['project_id'=>$p->id,'user_id'=>$r->user()->id,'event'=>$event,'details'=>$details]);}
public function index(Request $r){$q=$r->user()->projects()->withCount('tasks')->withSum('expenses','amount');if($r->filled('q'))$q->where('name','like','%'.$r->string('q').'%');if($r->filled('status'))$q->where('status',$r->string('status'));$projects=$q->latest()->get()->map(function($p){$n=$p->tasks_count;$p->progress=$n?round($p->tasks()->where('status','done')->count()*100/$n):0;$spent=(float)($p->expenses_sum_amount??0);$p->health=$p->planned_end&&$p->planned_end->isPast()&&$p->progress<100?'At risk':($p->budget!==null&&$spent>(float)$p->budget?'Over budget':'On track');return $p;});return view('projects.index',compact('projects'));}
public function store(Request $r){$d=$r->validate(['name'=>'required|string|max:120','description'=>'nullable|string|max:5000','status'=>'sometimes|in:active,on_hold,completed','planned_start'=>'nullable|date','planned_end'=>'nullable|date|after_or_equal:planned_start','budget'=>'nullable|numeric|min:0']);$p=DB::transaction(function()use($r,$d){$p=Project::create(['owner_id'=>$r->user()->id,'status'=>'active',...$d]);$p->members()->attach($r->user()->id,['role'=>'owner']);$this->log($p,$r,'Project created');return $p;});return redirect()->route('projects.show',$p);}
public function show(Request $r,int $id){$project=$this->scoped($r,$id);$tasks=$project->tasks()->with('assignee')->when($r->filled('q'),fn($q)=>$q->where('title','like','%'.$r->string('q').'%'))->when($r->filled('status'),fn($q)=>$q->where('status',$r->string('status')))->latest()->get();$members=$project->members()->get();$milestones=$project->milestones()->orderBy('due_date')->get();$risks=$project->risks()->latest()->get();$activities=$project->activities()->with('user')->latest()->limit(20)->get();$spent=(float)$project->expenses()->sum('amount');$total=$project->tasks()->count();$progress=$total?round($project->tasks()->where('status','done')->count()*100/$total):0;$overdue=$project->tasks()->whereNotNull('due_date')->whereDate('due_date','<',now())->where('status','!=','done')->count()+$project->milestones()->whereNotNull('due_date')->whereDate('due_date','<',now())->where('completed',false)->count();$health=$project->planned_end&&$project->planned_end->isPast()&&$progress<100?'At risk':($project->budget!==null&&$spent>(float)$project->budget?'Over budget':'On track');return view('projects.show',compact('project','tasks','members','milestones','risks','activities','spent','progress','overdue','health'));}
public function task(Request $r,int $id){$p=$this->scoped($r,$id);$d=$r->validate(['title'=>'required|string|max:180','description'=>'nullable|string|max:5000','status'=>'required|in:todo,in_progress,done','priority'=>'required|in:low,medium,high','due_date'=>'nullable|date','assignee_id'=>'nullable|exists:users,id']);if(!empty($d['assignee_id'])&&!$p->members()->whereKey($d['assignee_id'])->exists())abort(422);$t=$p->tasks()->create($d);$this->log($p,$r,'Task created',['title'=>$t->title]);return back();}
public function updateTask(Request $r,int $id,int $task){$p=$this->scoped($r,$id);$t=$p->tasks()->findOrFail($task);$d=$r->validate(['status'=>'required|in:todo,in_progress,done']);$old=$t->status;$t->update($d);$this->log($p,$r,'Task status changed',['task'=>$t->title,'from'=>$old,'to'=>$t->status]);return back();}
public function member(Request $r,int $id){$p=$this->scoped($r,$id);abort_unless($p->owner_id===$r->user()->id,403);$d=$r->validate(['email'=>'required|email|exists:users,email','role'=>'required|in:member,manager']);$u=\App\Models\User::where('email',$d['email'])->firstOrFail();$p->members()->syncWithoutDetaching([$u->id=>['role'=>$d['role']]]);$this->log($p,$r,'Project member added',['email'=>$u->email,'role'=>$d['role']]);return back();}
 public function milestone(Request $r,int $id){$p=$this->scoped($r,$id);$d=$r->validate(['name'=>'required|string|max:120','due_date'=>'nullable|date']);$p->milestones()->create($d);$this->log($p,$r,'Milestone created');return back();}
public function risk(Request $r,int $id){$p=$this->scoped($r,$id);$d=$r->validate(['kind'=>'required|in:risk,issue','title'=>'required|string|max:160','description'=>'required|string|max:3000','severity'=>'required|in:low,medium,high']);$p->risks()->create([...$d,'reported_by'=>$r->user()->id]);$this->log($p,$r,ucfirst($d['kind']).' recorded',['title'=>$d['title']]);return back();}
public function expense(Request $r,int $id){$p=$this->scoped($r,$id);if($p->budget===null)abort(403);$d=$r->validate(['description'=>'required|string|max:160','amount'=>'required|numeric|min:0.01','spent_at'=>'required|date']);$p->expenses()->create([...$d,'recorded_by'=>$r->user()->id]);$this->log($p,$r,'Expense recorded',['description'=>$d['description']]);return back();}
public function export(Request $r,int $id){$p=$this->scoped($r,$id);$n=$p->tasks()->count();$d=$p->tasks()->where('status','done')->count();$rows=[['Project','Status','Budget','Spent','Task count','Completed','Progress %','Open risks'],[$p->name,$p->status,$p->budget,$p->expenses()->sum('amount'),$n,$d,$n?round(100*$d/$n):0,$p->risks()->where('status','open')->count()]];$csv=implode("

",array_map(fn($row)=>implode(',',array_map(fn($v)=>'"'.str_replace('"','""',(string)$v).'"',$row)),$rows));return response($csv,200,['Content-Type'=>'text/csv','Content-Disposition'=>'attachment; filename=project-report.csv']);}
}
